import { Component, OnInit, ViewChild } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { ActionSheetController, IonFab, IonFabList } from '@ionic/angular';
import { UserSessionService } from 'src/app/services/usersession.service';
import { Storage } from '@ionic/storage';

@Component({
  selector: 'app-tnvntabs',
  templateUrl: './tnvntabs.page.html',
  styleUrls: ['./tnvntabs.page.scss'],
})
export class TnvntabsPage implements OnInit {
  fabButtonOpened: any;
  @ViewChild('fab') fab: IonFab;
  @ViewChild('fabList') fabList: IonFabList;
  fabMenuIsOpened = false;

  constructor(public actionSheetController: ActionSheetController, private userSessionService: UserSessionService,
    private router: Router, public activeRoute: ActivatedRoute, private ionicStorage:Storage) {
    this.fabButtonOpened = false;
  }

  ngOnInit() {
  }

  ionViewWillEnter() {
  }

  fabParent() {
    this.fabMenuIsOpened = !this.fabMenuIsOpened;
    this.fabList.activated = this.fabMenuIsOpened;
  }

  appLogout() {    
    let userName = window.localStorage.getItem('username');
    let password = window.localStorage.getItem('password');
    window.localStorage.clear();
    
    this.userSessionService.destroy();
    window.localStorage.setItem('username', userName);
    window.localStorage.setItem('password', password);
    this.router.navigate(['/login']);

    this.ionicStorage.forEach((value,key,index)=>{
      if(key != "studentListBy_school_id" && key != "teacherListBy_school_id" && key != "currentSchool_id"  && key != "learning_outcome" && key != 'store_observation' && key != 'learningOutcomeQues' && key !='schoolListBy_District_id'&& key != 'observation_list'){
        this.ionicStorage.remove(key)      
        }
    }) 
  }

  getOverlayStyle() {
    const myStyles = {
      width: '100%',
      height: '100%',      
      'background-color': 'rgba(0, 0, 0, 0.7)',      
      bottom: '0px !important',
      right: '0px !important',
    };
    const styleClosed = {
      bottom: '0px !important',
      right: '0px !important',
    };
    return this.fabMenuIsOpened ? myStyles : styleClosed;
  }

  goToHome() {    
    this.router.navigate(['tabs/home']);
  }

  goToNotifications() {    
    this.router.navigate(['tab/coomingsoon']);
  }

  goToSearch() {
    this.router.navigate(['tab/school']);
  }

  goToChangePassword() {
    this.router.navigate(['changepassword']);
  }

  goToSettings() 
  {
    this.router.navigate(['settings']);
  }
  goToHelp() {
  }
}